/* Phase 2 behaviour for the three controls the design declares but never draws.
 *
 * The triggers are the design's own: the sidebar and top-bar search boxes both
 * carry `data-action="openPalette"` (the top bar even renders a ⌘K hint), and
 * the bell carries `data-action="toggleNotif"`. What the design has no markup
 * for is what those actions *open* — so the panels are mine and the entry
 * points are not.
 *
 * The filter chips are enhanced in place rather than re-rendered. Their markup
 * is generated by tools/dc-to-ejs.js, which must stay free to overwrite it, so
 * nothing here edits the template — it reads the chips that are on the page and
 * attaches behaviour to them.
 *
 * actions.js keeps its own listener and ignores action names it does not know,
 * so the two files coexist without either one having to import the other.
 */
(function () {
  'use strict';

  const json = (id, fallback) => {
    const el = document.getElementById(id);
    if (!el) return fallback;
    try { return JSON.parse(el.textContent); } catch (_) { return fallback; }
  };

  const url = () => new URL(window.location.href);
  const go = (u) => { window.location.href = u.toString(); };

  /* ── Command palette ──────────────────────────────────────────────────── */

  const palette = {
    entries: json('li-palette-data', []),
    root: document.getElementById('li-palette'),
    input: document.getElementById('li-palette-input'),
    list: document.getElementById('li-palette-list'),
    shown: [],
    cursor: 0,
  };

  /* Every term must appear somewhere, in any order — so "kanban pipe" and
     "pipe kanban" both find the same row, which is how anyone actually types
     into a palette. */
  function match(entries, query) {
    const terms = query.toLowerCase().split(/\s+/).filter(Boolean);
    if (!terms.length) return entries;
    return entries.filter((e) => terms.every((t) => e.terms.includes(t)));
  }

  function renderPalette() {
    const query = palette.input.value.trim();
    palette.shown = match(palette.entries, query).slice(0, 60);
    palette.cursor = 0;

    if (!palette.shown.length) {
      palette.list.innerHTML = '<div class="li-palette-empty">Nothing matches “' +
        query.replace(/[<&]/g, '') + '”</div>';
      return;
    }

    palette.list.innerHTML = palette.shown.map((e, i) =>
      '<button type="button" class="li-row" role="option" data-i="' + i + '" aria-selected="' + (i === 0) + '">' +
        '<i class="' + e.icon + '"></i>' +
        '<span class="li-row-label">' + e.label + '</span>' +
        (e.context ? '<span class="li-row-context">' + e.context + '</span>' : '') +
      '</button>'
    ).join('');
  }

  function moveCursor(delta) {
    if (!palette.shown.length) return;
    const rows = palette.list.querySelectorAll('.li-row');
    rows[palette.cursor].setAttribute('aria-selected', 'false');
    palette.cursor = (palette.cursor + delta + rows.length) % rows.length;
    const row = rows[palette.cursor];
    row.setAttribute('aria-selected', 'true');
    row.scrollIntoView({ block: 'nearest' });
  }

  function openPalette() {
    if (!palette.root) return;
    palette.root.hidden = false;
    palette.input.value = '';
    renderPalette();
    palette.input.focus();
  }

  function closeOverlays() {
    if (palette.root) palette.root.hidden = true;
    const notifs = document.getElementById('li-notifs');
    if (notifs) notifs.hidden = true;
    closeMenu();
  }

  if (palette.root) {
    palette.input.addEventListener('input', renderPalette);

    palette.list.addEventListener('click', (ev) => {
      const row = ev.target.closest('.li-row');
      if (row) window.location.href = palette.shown[Number(row.dataset.i)].go;
    });

    palette.input.addEventListener('keydown', (ev) => {
      if (ev.key === 'ArrowDown') { ev.preventDefault(); moveCursor(1); }
      else if (ev.key === 'ArrowUp') { ev.preventDefault(); moveCursor(-1); }
      else if (ev.key === 'Enter') {
        ev.preventDefault();
        const entry = palette.shown[palette.cursor];
        if (entry) window.location.href = entry.go;
      }
    });
  }

  /* ── Notification panel ───────────────────────────────────────────────── */

  function toggleNotif() {
    const panel = document.getElementById('li-notifs');
    if (panel) panel.hidden = !panel.hidden;
  }

  /* The design hardcodes a badge of 4. Replace it with what the panel actually
     holds, and remove it at zero — a permanent unread count trains people to
     ignore the one time it means something. */
  function syncBadge() {
    const bell = document.querySelector('[data-action="toggleNotif"]');
    if (!bell) return;
    const badge = bell.querySelector('span');
    if (!badge) return;
    const count = json('li-notif-count', { count: 0 }).count;
    if (!count) { badge.remove(); return; }
    badge.textContent = String(count);
  }

  /* ── Filter chips ─────────────────────────────────────────────────────── */

  const filters = json('li-filter-data', { dimensions: [], inert: {}, active: {} });
  let menu = null;

  function closeMenu() {
    if (!menu) return;
    /* A menu that took focus has to give it back, or closing it strands the
       keyboard at the top of the document. */
    const opener = document.querySelector('[aria-expanded="true"]');
    const held = menu.contains(document.activeElement);
    menu.remove();
    menu = null;
    if (opener) {
      opener.setAttribute('aria-expanded', 'false');
      if (held && opener.focus) opener.focus();
    }
  }

  function openMenu(chip, dimension) {
    closeMenu();
    menu = document.createElement('div');
    menu.className = 'li-menu';

    const inertReason = filters.inert[dimension.chip];
    if (inertReason) {
      menu.innerHTML = '<div class="li-menu-inert">Not filterable — ' + inertReason + '.</div>';
    } else if (!dimension.options.length) {
      menu.innerHTML = '<div class="li-menu-inert">No row on this screen carries a ' +
        dimension.chip.toLowerCase() + '.</div>';
    } else {
      const current = filters.active[dimension.key] || 'All';
      const option = (value, label) =>
        '<button type="button" role="menuitemradio" data-v="' + value.replace(/"/g, '&quot;') + '"' +
        ' aria-checked="' + (value === current) + '">' + label + '<i class="ph ph-check"></i></button>';

      /* The label is not the value. `google` is what the URL carries and what
         the scope layer narrows on; "Google Ads" is what somebody is looking
         for in the list. Falls back to the value, so a dimension with no map
         reads exactly as before. */
      const labels = dimension.labels || {};
      /* Looked up case-insensitively because the screens disagree about how a
         channel is written — one table carries `google`, another `Google` — and
         both must read "Google Ads" in the menu. The value itself is left
         exactly as the rows carry it, since that is what a selection is
         compared against. */
      const labelOf = (o) => labels[o] || labels[String(o).toLowerCase()] || o;
      menu.innerHTML = option('All', 'All')
        + dimension.options.map((o) => option(o, labelOf(o))).join('');
    }

    const box = chip.getBoundingClientRect();
    menu.style.top = (box.bottom + 6) + 'px';
    menu.style.left = Math.min(box.left, window.innerWidth - 200) + 'px';
    document.body.appendChild(menu);

    menu.addEventListener('click', (ev) => {
      const btn = ev.target.closest('button');
      if (!btn) return;
      const u = url();
      if (btn.dataset.v === 'All') u.searchParams.delete('f_' + dimension.key);
      else u.searchParams.set('f_' + dimension.key, btn.dataset.v);
      go(u);
    });
  }

  /* ── Sort control ─────────────────────────────────────────────────────── */

  /* The design draws "Sort: Revenue" with a caret and nothing behind it — no
   * handler, no parameter, and no menu markup either. Phase 9 gave the caret a
   * destination so at least it cycled; a caret that cycles is still lying about
   * what it is, because a caret means "a list opens here".
   *
   * The list is built at runtime for the same reason the filter chips' is:
   * `views/screens/` is generated and must stay free to be overwritten. The
   * options come from the payload through `li-sort-data`, so the menu can never
   * offer a ranking the screen cannot actually perform.
   *
   * `data-action` stays on the control as the fallback. With JavaScript the
   * menu opens; without it the caret cycles as before. Neither state is a dead
   * control.
   */
  function enhanceSort(dataId, prefix) {
    const options = json(dataId, []);
    if (!options.length) return;

    /* Found by its caret and its own label rather than by a class the converter
       would have to know about — the same way presentation mode finds its
       three controls. */
    const control = Array.from(document.querySelectorAll('[data-action]')).find(
      (el) => el.querySelector('.ph-caret-down') && el.textContent.trim().indexOf(prefix) === 0,
    );
    if (!control) return;

    control.setAttribute('role', 'button');
    control.setAttribute('aria-haspopup', 'menu');

    control.addEventListener('click', (ev) => {
      /* Stops the document-level handler in actions.js from navigating to the
         next ranking behind the menu that just opened. */
      ev.stopPropagation();
      ev.preventDefault();
      if (menu) { closeMenu(); return; }

      closeMenu();
      menu = document.createElement('div');
      menu.className = 'li-menu';
      menu.setAttribute('role', 'menu');
      menu.innerHTML = options.map((o) =>
        '<button type="button" role="menuitemradio" data-go="' + o.go.replace(/"/g, '&quot;') + '"' +
        ' aria-checked="' + (o.active === true) + '">' + o.label + '<i class="ph ph-check"></i></button>'
      ).join('');

      const box = control.getBoundingClientRect();
      menu.style.top = (box.bottom + 6) + 'px';
      /* Right-aligned to the control: this one sits near the edge of the
         screen, and left-aligning it puts the menu half off the page. */
      menu.style.left = Math.max(8, Math.min(box.left, window.innerWidth - 190)) + 'px';
      document.body.appendChild(menu);

      menu.addEventListener('click', (e) => {
        const btn = e.target.closest('button');
        if (btn) window.location.href = btn.dataset.go;
      });
    });
  }

  /* ── The profile avatar ───────────────────────────────────────────────── */

  /* `POST /logout` has existed since Phase 9 and nothing in the interface ever
   * called it, so there was no way to sign out of this app. The avatar is where
   * a reader looks for that, and it opened nothing.
   *
   * Sign-out is a real form submission rather than a fetch: the route already
   * answers an HTML accept header with a redirect to /login, so a form gets the
   * navigation for free and still works if this script fails to load.
   *
   * A POST, not a link — signing out changes state, and a GET that ends a
   * session can be triggered by anything that prefetches a URL.
   */
  const escape = (s) => String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

  function openProfile(control) {
    closeMenu();
    /* Everything the menu shows comes from the server, through the same
       `application/json` channel the sort and filter controls use. The avatar
       can carry initials and a title and no more, and a menu built out of a
       title attribute can only ever repeat it. */
    const who = json('li-me-data', null) || { name: control.getAttribute('title') || 'Signed in' };

    menu = document.createElement('div');
    menu.className = 'li-menu li-profile';
    menu.setAttribute('role', 'menu');

    const rows = [];
    rows.push(
      '<div class="li-profile-head">'
      + '<span class="li-profile-face" aria-hidden="true">' + escape(who.initials || '?') + '</span>'
      + '<span class="li-profile-id"><strong>' + escape(who.name) + '</strong>'
      + (who.roleName ? '<span>' + escape(who.roleName) + '</span>' : '')
      + '</span></div>',
    );

    /* The workspace, said plainly. Every figure on every screen is scoped to it
       and the only other place it appears is a switcher that looks decorative,
       so a reader can be looking at one tenant's numbers believing otherwise. */
    if (who.workspaceName) {
      rows.push('<p class="li-profile-line"><i class="ph ph-buildings"></i>' + escape(who.workspaceName) + '</p>');
    }
    if (who.id) {
      rows.push('<p class="li-profile-line"><i class="ph ph-identification-badge"></i>Signed in as <code>'
        + escape(who.id) + '</code></p>');
    }

    /* What this role may do, from the table the server enforces — so the menu
       cannot promise something a request would be refused for. Named rather
       than counted: "6 of 9 permissions" tells a reader nothing they can act
       on, and which three are missing is the whole question. */
    if (who.can && who.can.length) {
      rows.push('<p class="li-profile-can">Can ' + who.can.map(escape).join(', ') + '.</p>');
    } else if (who.grants === 0) {
      rows.push('<p class="li-profile-can">Read-only — this role changes nothing.</p>');
    }

    rows.push('<div class="li-profile-acts">'
      + '<a role="menuitem" href="/connections"><i class="ph ph-plugs"></i>Connections</a>'
      + '<form method="post" action="/logout"><button type="submit" role="menuitem">'
      + '<i class="ph ph-sign-out"></i>Sign out</button></form></div>');

    menu.innerHTML = rows.join('');

    const box = control.getBoundingClientRect();
    menu.style.top = (box.bottom + 6) + 'px';
    /* Right-aligned: this control sits at the edge of the window, and
       left-aligning puts the menu off the page. */
    menu.style.left = Math.max(8, box.right - 236) + 'px';
    document.body.appendChild(menu);

    control.setAttribute('aria-expanded', 'true');
    /* Focus moves in, so the menu is reachable by keyboard rather than merely
       visible. `closeMenu` returns it. */
    const first = menu.querySelector('a, button');
    if (first) first.focus();
  }

  /* ── The date range ───────────────────────────────────────────────────── */

  /* The topbar's one date control, laid out like Shopify's: presets on the
   * left, the two days as text on top, a two-month calendar beneath, Cancel and
   * Apply at the foot. It replaced a row of seven chips plus a separate
   * From/To menu — two controls answering one question.
   *
   * The presets are the server's chips (`li-range-data`), so applying "Last 30
   * days" still sends `period=30d` and the link stays rolling. Yesterday and
   * the two quarters have no chip and are sent as a plain `from`/`to`.
   *
   * `to` is the last day the reader means. The server advances it by one,
   * because windows there are half-open — picking "1 Jul – 31 Jul" and silently
   * dropping the 31st is the same inclusive-`until` trap both ad connectors had
   * to solve.
   */
  function enhanceRange() {
    const control = document.querySelector('[data-li-range]');
    const data = json('li-range-data', null);
    if (!control || !data || !data.picker) return;

    const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July',
      'August', 'September', 'October', 'November', 'December'];
    const DOW = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    /* Days are `YYYY-MM-DD` strings and UTC dates throughout — the same day
       keys the server parses — so a reader east of UTC never picks the 1st and
       sends the 30th. */
    const iso = (d) => d.toISOString().slice(0, 10);
    const parse = (s) => new Date(s + 'T00:00:00Z');
    const addDays = (s, n) => { const d = parse(s); d.setUTCDate(d.getUTCDate() + n); return iso(d); };
    const local = new Date();
    const today = iso(new Date(Date.UTC(local.getFullYear(), local.getMonth(), local.getDate())));
    const pretty = (s) => { const d = parse(s); return MONTHS[d.getUTCMonth()] + ' ' + d.getUTCDate() + ', ' + d.getUTCFullYear(); };
    const ymd = (yy, mm, dd) => iso(new Date(Date.UTC(yy, mm, dd)));

    const t = parse(today);
    const y = t.getUTCFullYear();
    const m = t.getUTCMonth();
    const q = Math.floor(m / 3) * 3;

    /* Presets the server has no chip for, as plain ranges. */
    const extra = {
      yesterday: { name: 'Yesterday', from: addDays(today, -1), to: addDays(today, -1) },
      'this-quarter': { name: 'Quarter to date', from: ymd(y, q, 1), to: today },
      'last-quarter': { name: 'Last quarter', from: ymd(y, q - 3, 1), to: ymd(y, q, 0) },
    };
    /* What each chip covers, so picking one shows its days before Apply. */
    const span = {
      today: [today, today],
      '7d': [addDays(today, -7), today],
      '30d': [addDays(today, -30), today],
      '90d': [addDays(today, -90), today],
      'this-month': [ymd(y, m, 1), today],
      'last-month': [ymd(y, m - 1, 1), ymd(y, m, 0)],
      'this-year': [ymd(y, 0, 1), today],
    };
    const server = {};
    for (const p of data.presets || []) server[p.id] = p;
    const groups = [
      ['today', 'yesterday'],
      ['7d', '30d', '90d'],
      ['this-month', 'last-month', 'this-quarter', 'last-quarter', 'this-year'],
    ];
    const presetOf = (id) => {
      if (server[id] && span[id]) return { id, name: server[id].name, from: span[id][0], to: span[id][1], go: server[id].go };
      if (extra[id]) return Object.assign({ id }, extra[id]);
      return null;
    };
    /* A custom range that equals Yesterday or a quarter is named as that. */
    const matchExtra = (from, to) => Object.keys(extra).find((k) => extra[k].from === from && extra[k].to === to) || null;

    control.addEventListener('click', (ev) => {
      ev.stopPropagation();
      ev.preventDefault();
      if (menu && menu.classList.contains('li-dp')) { closeMenu(); return; }
      closeMenu();

      const start = data.picker;
      const state = {
        preset: start.active === 'custom' ? (matchExtra(start.from, start.to) || 'custom') : start.active,
        from: start.from || today,
        to: start.to || today,
        picking: false,
      };
      const initial = state.preset + '|' + state.from + '|' + state.to;
      /* The month holding the range's end sits on the right, as in the design. */
      const viewFor = (day) => { const d = parse(day); return { y: d.getUTCFullYear(), m: d.getUTCMonth() - 1 }; };
      let view = viewFor(state.to);

      menu = document.createElement('div');
      menu.className = 'li-menu li-dp';
      menu.setAttribute('role', 'dialog');
      menu.setAttribute('aria-label', 'Date range');
      control.setAttribute('aria-expanded', 'true');

      const month = (yy, mm) => {
        const first = new Date(Date.UTC(yy, mm, 1));
        const days = new Date(Date.UTC(yy, mm + 1, 0)).getUTCDate();
        const lo = state.from;
        const hi = state.to || state.from;
        let cells = '';
        for (let i = 0; i < first.getUTCDay(); i++) cells += '<span></span>';
        for (let d = 1; d <= days; d++) {
          const key = ymd(yy, mm, d);
          const cls = ['li-dp-day'];
          if (lo && key >= lo && key <= hi) cls.push('in');
          if (key === lo) cls.push('start');
          if (key === hi) cls.push('end');
          if (key === today) cls.push('today');
          cells += '<button type="button" class="' + cls.join(' ') + '" data-day="' + key + '"' +
            (key > today ? ' disabled' : '') + '>' + d + '</button>';
        }
        return '<div class="li-dp-month"><div class="li-dp-title">' + MONTHS[mm] + ' ' + yy + '</div>' +
          '<div class="li-dp-grid">' + DOW.map((w) => '<span class="li-dp-dow">' + w + '</span>').join('') + cells + '</div></div>';
      };

      const render = () => {
        const left = new Date(Date.UTC(view.y, view.m, 1));
        const right = new Date(Date.UTC(view.y, view.m + 1, 1));
        const changed = (state.preset + '|' + state.from + '|' + state.to) !== initial;
        const complete = Boolean(state.from && state.to && !state.picking);
        const presetButton = (id) => {
          const p = presetOf(id);
          if (!p) return '';
          return '<button type="button" data-preset="' + id + '" aria-checked="' + (state.preset === id) + '">' + p.name + '</button>';
        };
        menu.innerHTML =
          '<div class="li-dp-side">' +
            groups.map((g) => '<div class="li-dp-group">' + g.map(presetButton).join('') + '</div>').join('') +
            '<div class="li-dp-group"><button type="button" data-preset="custom" aria-checked="' + (state.preset === 'custom') + '">Custom range</button></div>' +
          '</div>' +
          '<div class="li-dp-main">' +
            '<div class="li-dp-fields">' +
              '<input type="text" data-field="from" aria-label="Start date" value="' + (state.from ? pretty(state.from) : '') + '">' +
              '<i class="ph ph-arrow-right" aria-hidden="true"></i>' +
              '<input type="text" data-field="to" aria-label="End date" placeholder="End date" value="' + (state.to ? pretty(state.to) : '') + '">' +
            '</div>' +
            '<div class="li-dp-cals">' +
              '<button type="button" class="li-dp-nav prev" data-nav="-1" aria-label="Previous month"><i class="ph ph-caret-left"></i></button>' +
              month(left.getUTCFullYear(), left.getUTCMonth()) +
              month(right.getUTCFullYear(), right.getUTCMonth()) +
              '<button type="button" class="li-dp-nav next" data-nav="1" aria-label="Next month"><i class="ph ph-caret-right"></i></button>' +
            '</div>' +
            '<p class="li-dp-error" hidden></p>' +
            '<div class="li-dp-foot">' +
              '<button type="button" data-cancel>Cancel</button>' +
              '<button type="button" data-apply class="primary"' + (changed && complete ? '' : ' disabled') + '>Apply</button>' +
            '</div>' +
          '</div>';
      };

      const error = (text) => {
        const el = menu.querySelector('.li-dp-error');
        el.textContent = text;
        el.hidden = !text;
      };

      const apply = () => {
        if (!state.from || !state.to || state.picking) return;
        const p = presetOf(state.preset);
        if (p && p.go) { window.location.href = p.go; return; }
        const [path, query] = start.base.split('?');
        const params = new URLSearchParams(query || '');
        params.set('from', state.from);
        params.set('to', state.to);
        window.location.href = path + '?' + params.toString();
      };

      /* Typed dates: anything Date can read — "Oct 3, 2026", "2026-10-03". */
      const typed = (input) => {
        const raw = input.value.trim();
        const ms = Date.parse(/^\d{4}-\d{2}-\d{2}$/.test(raw) ? raw + 'T00:00:00Z' : raw + ' UTC');
        if (!raw || !Number.isFinite(ms)) { render(); error('Type a date such as ' + pretty(today) + '.'); return; }
        const day = iso(new Date(ms));
        if (day > today) { render(); error('That day has not happened yet.'); return; }
        if (input.getAttribute('data-field') === 'from') state.from = day; else state.to = day;
        if (state.from && state.to && state.from > state.to) { const s = state.from; state.from = state.to; state.to = s; }
        state.picking = false;
        state.preset = matchExtra(state.from, state.to) || 'custom';
        view = viewFor(state.to);
        render();
      };

      /* Clicks inside re-render the menu, which detaches the clicked node — the
         document-level "click outside closes" check would then find the target
         in no menu at all and close this one. */
      menu.addEventListener('click', (e) => {
        e.stopPropagation();
        const day = e.target.closest('[data-day]');
        const preset = e.target.closest('[data-preset]');
        const nav = e.target.closest('[data-nav]');
        if (day && !day.disabled) {
          const key = day.getAttribute('data-day');
          if (!state.picking) { state.from = key; state.to = null; state.picking = true; }
          else if (key < state.from) { state.from = key; }
          else { state.to = key; state.picking = false; }
          state.preset = state.picking ? 'custom' : (matchExtra(state.from, state.to) || 'custom');
          render();
        } else if (preset) {
          const id = preset.getAttribute('data-preset');
          const p = presetOf(id);
          state.preset = id;
          state.picking = false;
          if (p) { state.from = p.from; state.to = p.to; view = viewFor(p.to); }
          render();
          if (id === 'custom') menu.querySelector('[data-field="from"]').focus();
        } else if (nav) {
          view.m += Number(nav.getAttribute('data-nav'));
          render();
        } else if (e.target.closest('[data-cancel]')) {
          closeMenu();
        } else if (e.target.closest('[data-apply]')) {
          apply();
        }
      });
      menu.addEventListener('change', (e) => { if (e.target.matches('[data-field]')) typed(e.target); });
      menu.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && e.target.matches('[data-field]')) { e.preventDefault(); typed(e.target); }
      });

      render();
      document.body.appendChild(menu);
      const box = control.getBoundingClientRect();
      menu.style.top = (box.bottom + 6) + 'px';
      menu.style.left = Math.max(8, Math.min(box.left, window.innerWidth - menu.offsetWidth - 8)) + 'px';
      const on = menu.querySelector('[aria-checked="true"]');
      if (on) on.focus();
    });
  }

  function enhanceChips() {
    /* Scoped to the main column: the sidebar's Full Funnel Analytics item
       carries the same icon and comes first, which bound every chip to the nav. */
    const funnel = document.querySelector('.main-col .ph-funnel-simple');
    const bar = funnel && funnel.parentElement;
    if (!bar) return;

    const byChip = {};
    for (const d of filters.dimensions) byChip[d.chip] = d;

    for (const chip of Array.from(bar.children)) {
      if (!chip.querySelector || !chip.querySelector('.ph-caret-down')) continue;
      const spans = chip.querySelectorAll('span');
      if (spans.length < 2) continue;

      const label = spans[0].textContent.trim();
      const dimension = byChip[label];
      if (!dimension && !filters.inert[label]) continue;

      const spec = dimension || { chip: label, key: null, options: [] };
      chip.setAttribute('role', 'button');
      chip.addEventListener('click', (ev) => {
        ev.stopPropagation();
        if (menu) { closeMenu(); return; }
        openMenu(chip, spec);
      });

      const active = spec.key && filters.active[spec.key];
      if (active) {
        /* Spelled the same way the menu spelled it — a chip reading "google"
           after picking "Google Ads" looks like it selected something else. */
        spans[1].textContent = (spec.labels && (spec.labels[active] || spec.labels[String(active).toLowerCase()])) || active;
        chip.classList.add('li-chip-active');
      }
    }
  }

  /* ── Keyboard access ──────────────────────────────────────────────────── */

  /* The design's click targets are `div`s and `span`s carrying `onClick`, which
     the converter preserves as `data-action`. A div is not focusable and does
     not fire on Enter, so every one of these — the whole sidebar, every tab,
     every drill-through row — is unreachable without a mouse.
   *
   * Fixed here rather than in the markup for the usual reason: `views/screens/`
   * is generated. Promoting them at runtime means a converter re-run cannot
   * undo it, and it applies to elements the design has not drawn yet.
   *
   * Space is handled as well as Enter, and its default is prevented — a
   * focused button that scrolls the page instead of activating is worse than
   * one that does nothing. */
  function makeOperable(el) {
    if (el.dataset.liOperable) return;
    el.dataset.liOperable = '1';

    /* Anything already focusable keeps its own semantics. */
    const tag = el.tagName.toLowerCase();
    if (tag === 'a' || tag === 'button' || tag === 'input' || tag === 'select') return;

    if (!el.hasAttribute('role')) el.setAttribute('role', 'button');
    if (!el.hasAttribute('tabindex')) el.setAttribute('tabindex', '0');

    /* A control with no text needs a name — the icon classes are the only
       description available, so the title attribute the design already sets is
       preferred and the icon is the fallback. */
    if (!el.getAttribute('aria-label') && !el.textContent.trim()) {
      const icon = el.querySelector('i[class*="ph-"]');
      const name = el.getAttribute('title')
        || (icon && (icon.className.match(/ph-([a-z-]+)/) || [])[1]);
      if (name) el.setAttribute('aria-label', name.replace(/-/g, ' '));
    }
  }

  function enhanceKeyboard(root) {
    for (const el of (root || document).querySelectorAll('[data-action]')) makeOperable(el);
  }

  /* Enter and Space activate, by dispatching the click the design's own
     handler is already listening for. */
  document.addEventListener('keydown', (ev) => {
    if (ev.key !== 'Enter' && ev.key !== ' ' && ev.key !== 'Spacebar') return;
    const el = ev.target.closest && ev.target.closest('[data-action]');
    if (!el || el.dataset.liOperable !== '1') return;

    const tag = el.tagName.toLowerCase();
    if (tag === 'a' || tag === 'button' || tag === 'input' || tag === 'select') return;

    ev.preventDefault();
    el.click();
  });

  /* ── Presentation mode ────────────────────────────────────────────────── */

  /* The design draws three controls on the presentation sub-view — TV mode,
     Dark room, Fullscreen — as plain spans with no `onClick`, so there is no
     `data-action` for the converter to preserve. They are found by their icons,
     which are the only stable thing about them, and the generated markup is
     left alone.

     What is *not* here: slide stepping. The design draws one slide and labels
     it "Slide 2 of 6", so the other five do not exist as markup. Stepping
     through a deck that was never defined would mean inventing five slides. */
  const PRESENT_CONTROLS = [
    { icon: 'ph-corners-out', action: toggleFullscreen },
    { icon: 'ph-moon', action: (el) => toggleClass(el, 'li-darkroom') },
    { icon: 'ph-television-simple', action: (el) => { toggleClass(el, 'li-tv'); toggleFullscreen(); } },
  ];

  function slide() {
    /* The 16:9 panel is the slide; it is the only aspect-ratio box on the page. */
    return document.querySelector('[style*="aspect-ratio:16/9"], [style*="aspect-ratio: 16/9"]');
  }

  function toggleFullscreen() {
    const target = slide() || document.documentElement;
    if (document.fullscreenElement) {
      document.exitFullscreen();
      return;
    }
    if (target.requestFullscreen) target.requestFullscreen().catch(() => {});
  }

  function toggleClass(el, className) {
    const on = document.body.classList.toggle(className);
    if (el) el.setAttribute('aria-pressed', String(on));
  }

  function wirePresentation() {
    for (const control of PRESENT_CONTROLS) {
      const icon = document.querySelector(`.${control.icon}`);
      const button = icon && icon.closest('span');
      if (!button) continue;
      button.setAttribute('role', 'button');
      button.setAttribute('aria-pressed', 'false');
      button.addEventListener('click', (ev) => { ev.preventDefault(); control.action(button); });
    }
  }

  /* ── Wiring ───────────────────────────────────────────────────────────── */

  document.addEventListener('click', (ev) => {
    if (ev.target.closest('[data-li-close]')) { closeOverlays(); return; }

    const trigger = ev.target.closest('[data-action]');
    if (trigger) {
      const action = trigger.getAttribute('data-action');
      if (action === 'openPalette') { ev.preventDefault(); openPalette(); return; }
      if (action === 'toggleTheme') { ev.preventDefault(); toggleTheme(); return; }
      if (action === 'toggleNotif') { ev.preventDefault(); toggleNotif(); return; }
      if (action === 'toggleProfile') {
        ev.preventDefault();
        /* Second click closes, like every other menu here. */
        if (menu && menu.classList.contains('li-profile')) { closeMenu(); return; }
        openProfile(trigger);
        return;
      }
    }

    if (menu && !ev.target.closest('.li-menu')) closeMenu();
  });

  document.addEventListener('keydown', (ev) => {
    if ((ev.metaKey || ev.ctrlKey) && ev.key.toLowerCase() === 'k') {
      ev.preventDefault();
      if (palette.root && palette.root.hidden) openPalette(); else closeOverlays();
      return;
    }
    if (ev.key === 'Escape') closeOverlays();
  });

  /* ── Theme ──────────────────────────────────────────────────────────────
   *
   * Three states, not two: an explicit light, an explicit dark, and no choice
   * at all — which follows the operating system. A toggle that only knew light
   * and dark would have to pick one as the default and would then ignore a
   * machine already set to light.
   *
   * The choice is stored per browser rather than per user. It is a preference
   * about a screen, not about an account: the same person on a bright phone
   * and a dim desk monitor wants different answers.
   *
   * The class is set on <html> before first paint by the inline-free bootstrap
   * at the top of this file — the CSP forbids inline scripts, so a brief flash
   * of dark is possible on a light-preferring machine. It is one frame and the
   * alternative is a cookie round trip on every request.
   */
  const THEME_KEY = 'leadintel.theme';

  function systemPrefersLight() {
    return window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches;
  }

  function currentTheme() {
    const stored = (() => { try { return localStorage.getItem(THEME_KEY); } catch (e) { return null; } })();
    if (stored === 'light' || stored === 'dark') return stored;
    return systemPrefersLight() ? 'light' : 'dark';
  }

  function paintTheme(theme) {
    document.documentElement.setAttribute('data-theme', theme);
    /* The icon shows what a click would DO, not what is on — a moon while dark
       is already on invites the reader to think they are in light mode. */
    for (const toggle of document.querySelectorAll('[data-li-theme-toggle] i')) {
      toggle.className = theme === 'light' ? 'ph ph-moon' : 'ph ph-sun';
    }
  }

  function applyTheme() { paintTheme(currentTheme()); }

  function toggleTheme() {
    const next = currentTheme() === 'light' ? 'dark' : 'light';
    try { localStorage.setItem(THEME_KEY, next); } catch (e) { /* private mode: the toggle still works for this page */ }
    paintTheme(next);
  }

  applyTheme();
  /* A machine that changes theme while the page is open follows, unless the
     reader has made a choice of their own. */
  if (window.matchMedia) {
    const query = window.matchMedia('(prefers-color-scheme: light)');
    const onChange = () => { try { if (!localStorage.getItem(THEME_KEY)) applyTheme(); } catch (e) { applyTheme(); } };
    if (query.addEventListener) query.addEventListener('change', onChange);
  }


  /* ── the sidebar, on a phone ───────────────────────────────────────────
   *
   * Below 860px app.css takes the sidebar out of the flow and parks it
   * off-canvas; this is the control that brings it back. Injected rather than
   * added to the markup because views/ is generated by tools/dc-to-ejs.js and
   * a re-run would drop a hand-added button — the same reason the filter chips
   * are enhanced in place rather than re-rendered.
   *
   * The class goes on , not on the nav, so the stylesheet decides what
   * open *means* — today a transform and a scrim, tomorrow whatever suits
   * without this file having to know.
   */
  function enhanceMobileNav() {
    const app = document.querySelector('.app');
    const header = document.querySelector('.main-col > header');
    const nav = app && app.querySelector(':scope > nav');
    if (!app || !header || !nav) return;

    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'li-navbtn';
    button.setAttribute('aria-label', 'Open navigation');
    button.setAttribute('aria-expanded', 'false');
    button.innerHTML = '<i class="ph ph-list" aria-hidden="true"></i>';

    const setOpen = (open) => {
      app.classList.toggle('li-nav-open', open);
      button.setAttribute('aria-expanded', String(open));
      button.setAttribute('aria-label', open ? 'Close navigation' : 'Open navigation');
    };

    button.addEventListener('click', (e) => {
      e.stopPropagation();
      setOpen(!app.classList.contains('li-nav-open'));
    });

    /* Tapping the scrim closes it. The scrim is the nav's own box-shadow, so
       there is no element to listen on — a click that lands outside the drawer
       and outside the button is the same gesture. */
    document.addEventListener('click', (e) => {
      if (!app.classList.contains('li-nav-open')) return;
      if (nav.contains(e.target) || button.contains(e.target)) return;
      setOpen(false);
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && app.classList.contains('li-nav-open')) setOpen(false);
    });

    /* Following a link is a navigation, and a drawer left open over the page
       it just loaded reads as a broken back button. */
    nav.addEventListener('click', (e) => {
      if (e.target.closest('a, [data-action]')) setOpen(false);
    });

    /* Rotating to landscape can cross the breakpoint, which leaves the class
       on an element the stylesheet no longer positions — the drawer would sit
       in the flow with a scrim behind it. */
    if (window.matchMedia) {
      const phone = window.matchMedia('(max-width: 860px)');
      const sync = () => { if (!phone.matches) setOpen(false); };
      if (phone.addEventListener) phone.addEventListener('change', sync);
    }

    header.insertBefore(button, header.firstChild);
  }

  /* A select that submits its own form.
   *
   * Written as an inline onchange first, which under this app's CSP
   * (script-src 'self', no unsafe-inline) is silently never run: the select
   * changed, the form never submitted, and the panel below went on describing
   * whatever was loaded. Generic rather than named after the one control that
   * needs it, so the next one does not repeat the mistake. */
  function enhanceAutoSubmit() {
    for (const el of document.querySelectorAll('[data-li-autosubmit]')) {
      el.addEventListener('change', () => {
        const form = el.closest('form');
        if (form) form.submit();
      });
    }
  }
  /* ── Auto-sync ────────────────────────────────────────────────────────
   *
   * The daily cron is the only schedule the hosting plan allows, so an open
   * app keeps the data fresh itself: it asks the server on load and every five
   * minutes while visible, and the server syncs only when the data is older
   * than its own threshold. Tabs share one clock in localStorage so ten open
   * tabs ask once. Nothing reloads under the reader — a finished sync offers a
   * Refresh instead. */
  function autoSync() {
    const pill = document.querySelector('[data-li-sync]');
    if (!pill) return;
    const dot = pill.querySelector('[data-li-sync-dot]');
    const label = pill.querySelector('[data-li-sync-label]');
    const KEY = 'li-auto-sync-asked';
    const ASK_EVERY = 5 * 60 * 1000;
    let lastAt = null;
    let pending = false;

    const ago = (iso) => {
      const m = Math.max(0, Math.round((Date.now() - new Date(iso).getTime()) / 60000));
      if (m < 1) return 'just now';
      if (m < 60) return m + 'm ago';
      const h = Math.round(m / 60);
      return h < 48 ? h + 'h ago' : Math.round(h / 24) + 'd ago';
    };
    const show = (text, color, title) => {
      pill.style.display = 'flex';
      label.textContent = text;
      dot.style.background = color;
      if (title) pill.title = title;
    };
    const idle = () => {
      if (lastAt) show('Synced ' + ago(lastAt), 'var(--color-accent-500)', 'Synced automatically every 15 minutes while the app is open. Click for Connections.');
    };
    const read = (k) => { try { return Number(localStorage.getItem(k)) || 0; } catch (e) { return 0; } };
    const write = (k, v) => { try { localStorage.setItem(k, String(v)); } catch (e) { /* private window */ } };

    async function ask(force) {
      if (pending || document.hidden) return;
      if (!force && Date.now() - read(KEY) < ASK_EVERY) { idle(); return; }
      write(KEY, Date.now());
      pending = true;
      const slow = setTimeout(() => show('Syncing…', 'var(--color-neutral-400)', 'Pulling the latest from every connected source'), 600);
      try {
        const res = await fetch('/connections/auto-sync', { method: 'POST', headers: { 'content-type': 'application/json', accept: 'application/json' }, body: '{}', credentials: 'same-origin' });
        clearTimeout(slow);
        if (!res.ok) { pill.style.display = 'none'; return; }
        const out = await res.json();
        if (out.lastAt) { lastAt = out.lastAt; write('li-auto-sync-last', new Date(out.lastAt).getTime()); }
        if (out.state === 'synced') {
          const issues = (out.failed || []).length + (out.running || []).length;
          if (out.written > 0) {
            show('New data · Refresh', 'var(--color-accent-500)', 'Synced ' + out.written + ' new row(s). Click to reload this page.');
            pill.setAttribute('href', location.pathname + location.search);
          } else idle();
          if (issues) show(label.textContent + ' · ' + issues + ' issue(s)', 'var(--color-warning-500, #d9a03f)', [...(out.failed || []), ...(out.running || []).map((n) => n + ' did not finish')].join('\n'));
        } else idle();
      } catch (e) {
        clearTimeout(slow);
      } finally {
        pending = false;
      }
    }

    const stored = read('li-auto-sync-last');
    if (stored) { lastAt = new Date(stored).toISOString(); idle(); }
    ask(false);
    setInterval(() => { if (!document.hidden) ask(false); else idle(); }, 60 * 1000);
    document.addEventListener('visibilitychange', () => { if (!document.hidden) ask(false); });
  }

  /* ── Chart click panels ──────────────────────────────────────────────
   *
   * Every mark on the dashboard infographics carries `data-li-pop` — a title,
   * label/value rows and, where a screen can answer the next question, a link
   * (lib/dashboard-charts.js). A <title> tooltip alone did nothing on click and
   * nothing at all on a phone. A link with no range of its own is given the
   * page's, so drilling in keeps the dates being read. */
  function chartPops() {
    let open = null;
    let openFor = null;
    const close = () => {
      if (open) open.remove();
      if (openFor) openFor.classList.remove('li-pop-on');
      open = null; openFor = null;
    };
    const withRange = (href) => {
      try {
        const url = new URL(href, location.origin);
        const here = new URLSearchParams(location.search);
        if (!url.searchParams.has('from') && !url.searchParams.has('period')) {
          for (const k of ['period', 'from', 'to']) if (here.get(k)) url.searchParams.set(k, here.get(k));
        }
        return url.pathname + url.search;
      } catch (e) { return href; }
    };
    const esc = (t) => String(t == null ? '' : t).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
    const show = (mark, x, y) => {
      let data;
      try { data = JSON.parse(mark.getAttribute('data-li-pop')); } catch (e) { return; }
      if (!data) return;
      if (openFor === mark) { close(); return; }
      close();
      const box = document.createElement('div');
      box.className = 'li-pop';
      box.setAttribute('role', 'dialog');
      box.innerHTML = '<div class="li-pop-h"><span>' + esc(data.title) + '</span><button type="button" class="li-pop-x" aria-label="Close">×</button></div>'
        + '<div class="li-pop-rows">' + (data.rows || []).map((r) => '<div><span>' + esc(r[0]) + '</span><strong>' + esc(r[1]) + '</strong></div>').join('') + '</div>'
        + (data.go ? '<a class="li-pop-go" href="' + esc(withRange(data.go)) + '">' + esc(data.goText || 'Open') + ' →</a>' : '');
      document.body.appendChild(box);
      const w = box.offsetWidth;
      const h = box.offsetHeight;
      const left = Math.min(Math.max(8, x - w / 2), window.innerWidth - w - 8);
      const top = y - h - 12 > 8 ? y - h - 12 : Math.min(y + 14, window.innerHeight - h - 8);
      box.style.left = left + 'px';
      box.style.top = top + 'px';
      box.querySelector('.li-pop-x').addEventListener('click', close);
      open = box; openFor = mark;
      mark.classList.add('li-pop-on');
      const go = box.querySelector('.li-pop-go');
      if (go && mark.matches(':focus-visible')) go.focus();
    };
    document.addEventListener('click', (e) => {
      if (open && open.contains(e.target)) return;
      const mark = e.target.closest && e.target.closest('[data-li-pop]');
      if (!mark) { close(); return; }
      e.preventDefault();
      show(mark, e.clientX, e.clientY);
    });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') { close(); return; }
      if ((e.key === 'Enter' || e.key === ' ') && e.target.matches && e.target.matches('[data-li-pop]')) {
        e.preventDefault();
        const r = e.target.getBoundingClientRect();
        show(e.target, r.left + r.width / 2, r.top);
      }
    });
    window.addEventListener('scroll', close, { passive: true });
    window.addEventListener('resize', close);
  }

  syncBadge();
  autoSync();
  chartPops();
  enhanceChips();
  enhanceRange();
  enhanceSort('li-sort-data', 'Sort:');
  enhanceSort('li-goal-data', 'Judge by:');
  wirePresentation();
  enhanceAutoSubmit();
  enhanceMobileNav();
  enhanceKeyboard();
})();
